"use client"

import * as React from "react"
import { CircleAlert, LoaderCircle, MapPin, RotateCw, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { findPostcodeProblem, normalizePostcode, pinRegion, POSTCODE_SHAPES, sameCity, sameState, type PinPlace, type PostcodeProblem } from "./pincode"

export * from "./pincode"

/** Default messages. `{pin}`, `{fixed}`, `{length}`, `{prefix}`, `{name}`, `{label}`, `{state}`, `{typed}`, `{city}`, `{count}` are filled in. */
export const PINCODE_MESSAGES = {
  "letter-digit": "That has a letter where a digit should be (O for 0, I for 1).",
  "extra-text": "There's other text around the PIN.",
  length: "PIN codes have 6 digits. This one has {length}.",
  "leading-zero": "No PIN code starts with 0.",
  unassigned: "No PIN code starts with {prefix}. Check the first two digits.",
  army: "PINs starting with 9 are only for the Army Postal Service.",
  "other-country": "That looks like a {name} {label}, not an Indian PIN.",
  invalid: "That doesn't look like a postcode for this country.",
  "no-postcodes": "The UAE doesn't use postcodes. You can leave this empty.",
  useFixed: "Use {fixed}",
  switchCountry: "Switch country",
  inState: "{prefix}… is in {state}",
  stateMismatch: "{pin} is in {state}, but the state says {typed}.",
  useState: "Use {state}",
  cityMismatch: "{pin} is in {city}, not {typed}.",
  useCity: "Use {city}",
  checking: "Finding the area…",
  failed: "Couldn't look up this PIN.",
  retry: "Retry",
  notFound: "No post office uses {pin}. Check it on a recent letter or bill.",
  moreAreas: "+{count} more",
  or: "or",
}

type Lookup = { pin: string; state: "checking" } | { pin: string; state: "done"; place: PinPlace | null } | { pin: string; state: "failed" }
const fill = (s: string, d: Record<string, string>) => s.replace(/\{(\w+)\}/g, (m, k: string) => d[k] ?? m)
const fixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 font-medium whitespace-nowrap text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"

export interface PincodeInputProps extends Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "onChange"> {
  /** Visible label. */
  label?: string
  /** Controlled code (other-script digits converted, spaces removed for India). */
  value?: string
  /** Initial code when uncontrolled. */
  defaultValue?: string
  /** Called with the cleaned code on every change. */
  onValueChange?: (value: string) => void
  /** ISO country the address is in. India gets full PIN checks; others get a shape check. */
  country?: string
  /** Offered as a one-tap switch when the code looks like it belongs to another country. */
  onCountryChange?: (country: string) => void
  /** The state picked elsewhere in the form, checked against the PIN. */
  state?: string
  /** Lets the user take the PIN's state in one tap. */
  onUseState?: (state: string) => void
  /** The city typed elsewhere in the form, checked against the lookup. */
  city?: string
  /** Lets the user take the PIN's district in one tap. */
  onUseCity?: (city: string) => void
  /** Finds where a complete Indian PIN is. Resolve null when no post office has it. See createIndiaPostLookup. */
  lookup?: (pin: string, signal: AbortSignal) => Promise<PinPlace | null>
  /** Called with the place once found, or null when the PIN changes or isn't found. */
  onPlaceChange?: (place: PinPlace | null) => void
  /** Override any message or label. */
  messages?: Partial<typeof PINCODE_MESSAGES>
}

/**
 * A PIN code field that stops parcels going to the wrong place. It reads the
 * state from the PIN's first digits as you type (no network needed) and warns
 * when it disagrees with the state picked, catches O typed for 0, a wrong
 * length, prefixes no PIN uses, Army Post codes and a ZIP or UK postcode typed
 * for India, then reads the area back from your lookup and checks the city.
 */
export function PincodeInput({
  label = "PIN code",
  value,
  defaultValue = "",
  onValueChange,
  country = "IN",
  onCountryChange,
  state,
  onUseState,
  city,
  onUseCity,
  lookup,
  onPlaceChange,
  messages,
  id,
  className,
  onBlur,
  ref,
  "aria-describedby": describedBy,
  ...props
}: PincodeInputProps) {
  const t = { ...PINCODE_MESSAGES, ...messages }
  const india = country === "IN"
  const clean = React.useCallback((raw: string) => (india ? normalizePostcode(raw).replace(/[\s-]/g, "") : normalizePostcode(raw).toUpperCase()), [india])
  const [inner, setInner] = React.useState(() => clean(defaultValue))
  // The value being typed right now. Anything else (prefilled, autofilled, set by code) is checked as complete.
  const [typing, setTyping] = React.useState<string | null>(null)
  const [result, setResult] = React.useState<Lookup>()
  const [attempt, setAttempt] = React.useState(0)
  const inputRef = React.useRef<HTMLInputElement>(null)
  React.useImperativeHandle(ref, () => inputRef.current as HTMLInputElement)
  const autoId = React.useId()
  const inputId = id ?? autoId
  const code = value ?? inner
  const complete = india && /^[1-8]\d{5}$/.test(code)
  const lookupRef = React.useRef(lookup)
  const placeRef = React.useRef(onPlaceChange)
  React.useEffect(() => {
    lookupRef.current = lookup
    placeRef.current = onPlaceChange
  })

  React.useEffect(() => {
    if (!complete || !lookupRef.current) return
    const controller = new AbortController()
    const timer = setTimeout(() => {
      setResult({ pin: code, state: "checking" })
      lookupRef.current!(code, controller.signal).then(
        (place) => {
          if (controller.signal.aborted) return
          setResult({ pin: code, state: "done", place })
          placeRef.current?.(place)
        },
        () => !controller.signal.aborted && setResult({ pin: code, state: "failed" })
      )
    }, 250)
    return () => {
      clearTimeout(timer)
      controller.abort()
    }
  }, [code, complete, attempt])

  const update = (raw: string) => {
    const next = clean(raw).slice(0, 120)
    if (value === undefined) setInner(next)
    if (next !== code) placeRef.current?.(null)
    onValueChange?.(next)
    return next
  }

  const current = result?.pin === code ? result : undefined
  const place = current?.state === "done" ? current.place : undefined
  const problem: PostcodeProblem | null = findPostcodeProblem(code, country, typing !== code || code.length >= 6)
  const region = india && !problem ? pinRegion(code) : null
  const pinStates = place ? [place.state] : region?.kind === "state" ? region.states : []
  const stateOff = !!state && pinStates.length > 0 && !pinStates.some((s) => sameState(s, state))
  const cityOff = !!city && !!place && !sameCity(city, place)
  const d: Record<string, string> = { pin: code, typed: "", prefix: code.slice(0, india ? 3 : 2), state: pinStates.join(` ${t.or} `) }
  if (problem?.kind === "letter-digit" || problem?.kind === "extra-text") d.fixed = problem.fixed
  if (problem?.kind === "length") d.length = String(problem.length)
  if (problem?.kind === "unassigned") d.prefix = problem.prefix
  if (problem?.kind === "other-country") Object.assign(d, POSTCODE_SHAPES[problem.country] ?? { name: "Indian", label: "PIN code" })

  const warn = (key: string, text: React.ReactNode, action?: React.ReactNode) => (
    <p key={key} className="flex gap-1.5 text-amber-700 dark:text-amber-400">
      <span className="flex h-6 shrink-0 items-center"><TriangleAlert aria-hidden className="size-3.5" /></span>
      <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1"><span className="py-1">{text}</span>{action}</span>
    </p>
  )

  return (
    <div data-slot="pincode-input" className={cn("grid w-full max-w-sm gap-1.5", className)}>
      <style>{`@keyframes cui-pincode-input-reveal{from{opacity:0;transform:translateY(-4px)}}`}</style>
      <label htmlFor={inputId} className="w-fit text-sm font-medium">{label}</label>
      <input
        ref={inputRef}
        id={inputId}
        autoComplete="postal-code"
        inputMode={india ? "numeric" : "text"}
        autoCorrect="off"
        spellCheck={false}
        placeholder={india ? "e.g. 411039" : undefined}
        value={code}
        onChange={(e) => setTyping(update(e.target.value))}
        onBlur={(e) => {
          setTyping(null)
          onBlur?.(e)
        }}
        aria-describedby={[`${inputId}-status`, describedBy].filter(Boolean).join(" ")}
        aria-invalid={place === null || undefined}
        data-warning={problem || stateOff ? "" : undefined}
        className="h-9 w-full min-w-0 rounded-md border bg-transparent px-3 font-mono text-base tracking-wider shadow-xs transition-[color,box-shadow] outline-none placeholder:font-sans placeholder:tracking-normal placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive md:text-sm dark:bg-input/30 data-warning:border-amber-500 dark:data-warning:border-amber-400"
        {...props}
      />
      <div id={`${inputId}-status`} aria-live="polite" className="grid min-h-6 gap-1.5 text-xs">
        {problem &&
          warn(
            "problem",
            fill(t[problem.kind], d),
            problem.kind === "letter-digit" || problem.kind === "extra-text" ? (
              <button
                type="button"
                onClick={() => {
                  update(problem.fixed)
                  inputRef.current?.focus()
                }}
                className={fixClass}
              >
                {fill(t.useFixed, d)}
              </button>
            ) : problem.kind === "other-country" && onCountryChange ? (
              <button type="button" onClick={() => onCountryChange(problem.country)} className={fixClass}>{t.switchCountry}</button>
            ) : undefined
          )}
        {!problem && !complete && region?.kind === "state" && !stateOff && (
          <p className="py-1 text-muted-foreground">{fill(t.inState, d)}</p>
        )}
        {stateOff &&
          warn(
            "state",
            fill(t.stateMismatch, { ...d, typed: state! }),
            onUseState && pinStates.length === 1 && (
              <button type="button" onClick={() => onUseState(pinStates[0])} className={fixClass}>{fill(t.useState, d)}</button>
            )
          )}
        {current?.state === "checking" && (
          <p className="flex items-center gap-1.5 py-1 text-muted-foreground motion-safe:animate-pulse">
            <LoaderCircle aria-hidden className="size-3.5 animate-spin" /> {t.checking}
          </p>
        )}
        {current?.state === "failed" &&
          warn("failed", t.failed, (
            <button type="button" onClick={() => setAttempt((n) => n + 1)} className={fixClass}><RotateCw aria-hidden className="size-3" /> {t.retry}</button>
          ))}
        {place === null && (
          <div role="alert" className="flex gap-2 rounded-md border border-red-500/30 bg-red-500/10 px-2.5 py-2 text-sm text-red-900 motion-safe:animate-[cui-pincode-input-reveal_250ms_ease-out] dark:text-red-100">
            <CircleAlert aria-hidden className="mt-0.5 size-4 shrink-0 text-red-600 dark:text-red-400" />
            <p>{fill(t.notFound, d)}</p>
          </div>
        )}
        {place && (
          <div className="flex gap-2.5 rounded-md border bg-muted/40 px-3 py-2.5 text-sm motion-safe:animate-[cui-pincode-input-reveal_250ms_ease-out]">
            <MapPin aria-hidden className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
            <div className="grid min-w-0 gap-0.5">
              <p className="font-medium">
                {place.district}, {place.state}
              </p>
              {!!place.areas?.length && (
                <p className="text-muted-foreground">
                  {place.areas.slice(0, 2).join(", ")}
                  {place.areas.length > 2 && ` ${fill(t.moreAreas, { count: String(place.areas.length - 2) })}`}
                </p>
              )}
            </div>
          </div>
        )}
        {cityOff &&
          warn(
            "city",
            fill(t.cityMismatch, { ...d, city: place!.district, typed: city! }),
            onUseCity && <button type="button" onClick={() => onUseCity(place!.district)} className={fixClass}>{fill(t.useCity, { city: place!.district })}</button>
          )}
      </div>
    </div>
  )
}

/** Pure Indian PIN and postcode checks. No React. Prefix table from India Post via Wikipedia "Postal Index Number". */

/** First digits of a PIN → state or UT. Longer prefixes win (403 is Goa inside Maharashtra's 40–44). */
const PREFIXES: [string, string][] = [
  ["11", "Delhi"], ["12", "Haryana"], ["13", "Haryana"], ["14", "Punjab"], ["15", "Punjab"], ["16", "Chandigarh"],
  ["17", "Himachal Pradesh"], ["18", "Jammu and Kashmir"], ["19", "Jammu and Kashmir|Ladakh"],
  ...["20", "21", "22", "23", "24", "25", "26", "27", "28"].map((p): [string, string] => [p, "Uttar Pradesh|Uttarakhand"]),
  ...["30", "31", "32", "33", "34"].map((p): [string, string] => [p, "Rajasthan"]),
  ...["36", "37", "38", "39"].map((p): [string, string] => [p, "Gujarat"]),
  ["396", "Gujarat|Dadra and Nagar Haveli and Daman and Diu"],
  ...["40", "41", "42", "43", "44"].map((p): [string, string] => [p, "Maharashtra"]), ["403", "Goa"],
  ...["45", "46", "47", "48"].map((p): [string, string] => [p, "Madhya Pradesh"]), ["49", "Chhattisgarh"],
  ["50", "Telangana"], ["51", "Andhra Pradesh"], ["52", "Andhra Pradesh"], ["53", "Andhra Pradesh"],
  ...["56", "57", "58", "59"].map((p): [string, string] => [p, "Karnataka"]),
  ...["60", "61", "62", "63", "64", "65", "66"].map((p): [string, string] => [p, "Tamil Nadu"]), ["605", "Puducherry|Tamil Nadu"],
  ...["67", "68", "69"].map((p): [string, string] => [p, "Kerala"]), ["682", "Kerala|Lakshadweep"],
  ...["70", "71", "72", "73", "74"].map((p): [string, string] => [p, "West Bengal"]), ["737", "Sikkim"], ["744", "Andaman and Nicobar Islands"],
  ...["75", "76", "77"].map((p): [string, string] => [p, "Odisha"]), ["78", "Assam"],
  ["790", "Arunachal Pradesh"], ["791", "Arunachal Pradesh"], ["792", "Arunachal Pradesh"], ["793", "Meghalaya"], ["794", "Meghalaya"],
  ["795", "Manipur"], ["796", "Mizoram"], ["797", "Nagaland"], ["798", "Nagaland"], ["799", "Tripura"],
  ...["80", "81", "82", "83", "84", "85"].map((p): [string, string] => [p, "Bihar|Jharkhand"]),
]
const BY_PREFIX = new Map(PREFIXES)

export type PinRegion = { kind: "state"; states: string[] } | { kind: "army" } | { kind: "unassigned"; prefix: string }

/** Where a PIN (or its first 2–3 digits) belongs, from its prefix alone, with no network call. */
export function pinRegion(pin: string): PinRegion | null {
  if (!/^\d{2,}/.test(pin)) return null
  if (pin[0] === "9") return { kind: "army" }
  if (pin.length === 2) {
    // Two digits can't tell Goa (403) from Maharashtra (40) or Sikkim (737) from West Bengal (73), so name every candidate.
    const states = PREFIXES.filter(([p]) => p.startsWith(pin)).flatMap(([, s]) => s.split("|"))
    return states.length ? { kind: "state", states: [...new Set(states)] } : { kind: "unassigned", prefix: pin }
  }
  const hit = BY_PREFIX.get(pin.slice(0, 3)) ?? BY_PREFIX.get(pin.slice(0, 2))
  return hit ? { kind: "state", states: hit.split("|") } : { kind: "unassigned", prefix: pin.slice(0, 2) }
}

// Zero of every Indic script plus Arabic-Indic and fullwidth digits.
const ZEROS = [0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66, 0x0be6, 0x0c66, 0x0ce6, 0x0d66, 0x0660, 0x06f0, 0xff10]

/** Converts other-script digits to 0–9 and drops spaces, dashes and a leading "PIN"/"Pincode" label. Letters stay. */
export function normalizePostcode(raw: string) {
  const ascii = [...raw]
    .map((c) => {
      const code = c.codePointAt(0)!
      const zero = ZEROS.find((z) => code >= z && code <= z + 9)
      return zero === undefined ? c : String(code - zero)
    })
    .join("")
  return ascii.replace(/^\s*(pin\s*code|pincode|pin|zip)\s*[:\-]?\s*/i, "")
}

/** Postcode shapes used to notice a code from another country. India is checked separately. */
export const POSTCODE_SHAPES: Record<string, { name: string; label: string; pattern: RegExp | null }> = {
  US: { name: "US", label: "ZIP code", pattern: /^\d{5}(-\d{4})?$/ },
  GB: { name: "UK", label: "postcode", pattern: /^[A-PR-UWYZ][A-HK-Y]?\d[A-Z\d]? ?\d[ABD-HJLNP-UW-Z]{2}$/i },
  CA: { name: "Canadian", label: "postal code", pattern: /^[ABCEGHJ-NPRSTVXY]\d[A-Z] ?\d[A-Z]\d$/i },
  NL: { name: "Dutch", label: "postcode", pattern: /^[1-9]\d{3} ?[A-RT-Z]{2}$/i },
  JP: { name: "Japanese", label: "postal code", pattern: /^\d{3}-\d{4}$/ },
  AU: { name: "Australian", label: "postcode", pattern: /^\d{4}$/ },
  SG: { name: "Singapore", label: "postal code", pattern: /^\d{6}$/ },
  DE: { name: "German", label: "postcode", pattern: /^\d{5}$/ },
  AE: { name: "UAE", label: "postcode", pattern: null },
}

export type PostcodeProblem =
  | { kind: "letter-digit"; fixed: string }
  /** A PIN pasted with other text around it ("Pune - 411039"). `fixed` is the PIN alone. */
  | { kind: "extra-text"; fixed: string }
  | { kind: "length"; length: number; expected: number }
  | { kind: "leading-zero" }
  | { kind: "unassigned"; prefix: string }
  | { kind: "army" }
  | { kind: "other-country"; country: string }
  | { kind: "invalid" }
  | { kind: "no-postcodes" }

/** The first problem with a postcode for a country (ISO code), or null. `complete` is false while still typing. */
export function findPostcodeProblem(code: string, country = "IN", complete = true): PostcodeProblem | null {
  if (!code) return null
  if (country === "IN") {
    const compact = code.replace(/[\s-]/g, "")
    const fixed = compact.replace(/[oO]/g, "0").replace(/[lIi|]/g, "1")
    if (fixed !== compact && /^\d+$/.test(fixed)) return { kind: "letter-digit", fixed }
    const runs = code.match(/(?<!\d)[1-8]\d{5}(?!\d)/g)
    if (runs?.length === 1 && /[a-z]/i.test(compact)) return { kind: "extra-text", fixed: runs[0] }
    if (/[a-z]/i.test(compact) || /^\d{5}(-\d{4})?$/.test(code) || /^\d{3}-\d{4}$/.test(code)) {
      const other = Object.keys(POSTCODE_SHAPES).find((c) => c !== "SG" && c !== "AU" && POSTCODE_SHAPES[c].pattern?.test(code.trim()))
      if (other && (complete || /[a-z]/i.test(compact))) return { kind: "other-country", country: other }
      if (/[a-z]/i.test(compact)) return { kind: "invalid" }
    }
    if (compact[0] === "0") return { kind: "leading-zero" }
    const region = pinRegion(compact)
    if (region?.kind === "unassigned") return region
    if (compact.length > 6 || (complete && compact.length !== 6)) return { kind: "length", length: compact.length, expected: 6 }
    if (region?.kind === "army" && compact.length === 6) return { kind: "army" }
    return null
  }
  const shape = POSTCODE_SHAPES[country]
  if (!shape) return null
  if (!shape.pattern) return { kind: "no-postcodes" }
  if (!complete || shape.pattern.test(code.trim())) return null
  if (/^[1-8]\d{5}$/.test(code.replace(/\s/g, ""))) return { kind: "other-country", country: "IN" }
  return { kind: "invalid" }
}

/** Old and new names for the same city, so "Bombay" matches "Mumbai". */
const CITY_ALIASES: Record<string, string> = {
  bombay: "mumbai", poona: "pune", bangalore: "bengaluru", calcutta: "kolkata", madras: "chennai", gurgaon: "gurugram",
  trivandrum: "thiruvananthapuram", baroda: "vadodara", mysore: "mysuru", cochin: "kochi", benares: "varanasi", pondicherry: "puducherry",
}
const cityKey = (s: string) => {
  const k = s.toLowerCase().replace(/\b(city|district|urban|rural|east|west|north|south|central|new)\b/g, "").replace(/[^a-z]/g, "")
  return CITY_ALIASES[k] ?? k
}
/** True when a typed city matches the looked-up district or any area name. */
export function sameCity(typed: string, place: { district: string; areas?: string[] }) {
  const key = cityKey(typed)
  const names = [place.district, ...(place.areas ?? [])]
  // Any shared word of 4+ letters also counts: "Pimpri Chinchwad" vs the "Pimpri Colony" post office.
  const words = (s: string) => s.toLowerCase().split(/[^a-z]+/).filter((w) => w.length >= 4).map((w) => CITY_ALIASES[w] ?? w)
  const typedWords = words(typed)
  return (
    !key ||
    names.some((n) => {
      const other = cityKey(n)
      return (!!other && (other.includes(key) || key.includes(other))) || words(n).some((w) => typedWords.includes(w))
    })
  )
}
const STATE_ALIASES: Record<string, string> = { orissa: "odisha", uttaranchal: "uttarakhand", pondicherry: "puducherry", nctdelhi: "delhi" }
const stateKey = (s: string) => {
  // "Jammu & Kashmir" = "Jammu and Kashmir", "NCT of Delhi" = "Delhi", "Orissa" = "Odisha".
  const k = s.toLowerCase().replace(/&/g, " and ").replace(/\b(and|of|the|state|ut)\b/g, "").replace(/[^a-z]/g, "")
  return STATE_ALIASES[k] ?? k
}
/** True when two state names mean the same state, allowing "&" for "and" and old names. */
export const sameState = (a: string, b: string) => stateKey(a) === stateKey(b)

/** Where a PIN is, as your lookup returns it. */
export interface PinPlace {
  /** District or city, e.g. "Pune". */
  district: string
  state: string
  /** Post office or locality names sharing the PIN, e.g. ["Bhosari", "Dighi Camp"]. */
  areas?: string[]
}

/** A lookup for India Post's public API (api.postalpincode.in). Resolves null when no post office has the PIN. */
export function createIndiaPostLookup(base = "https://api.postalpincode.in/pincode/") {
  return async (pin: string, signal: AbortSignal): Promise<PinPlace | null> => {
    const res = await fetch(base + pin, { signal })
    if (!res.ok) throw new Error(`PIN lookup failed: ${res.status}`)
    const [data] = (await res.json()) as { Status: string; PostOffice: { Name: string; District: string; State: string }[] | null }[]
    const offices = data?.Status === "Success" ? data.PostOffice ?? [] : []
    if (!offices.length) return null
    return { district: offices[0].District, state: offices[0].State, areas: offices.map((o) => o.Name) }
  }
}
